using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Mirror of Life Trapping (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class MirrorOfLifeTrapping2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("mirror-of-life-trapping", null, 0, MagicItemType.WondrousItem, ItemRarity.VeryRare, false, ContentSource.Srd51,
			null,
			("Specchio imprigionante", "Oggetto meraviglioso, molto raro",
			"Se si osserva indirettamente la superficie di questo specchio alto 1,2 metri, esso mostra flebili immagini di alcune creature. Lo specchio pesa 25 kg, ha CA 11, 10 punti ferita ed è vulnerabile ai danni contundenti. Quando scende a 0 punti ferita, va in pezzi ed è distrutto.\n\nSe lo specchio è appeso a una superficie verticale e il personaggio si trova entro 1,5 metri da esso, può usare un'azione per pronunciare la sua parola d'ordine e attivarlo. Lo specchio resta attivo finché il personaggio non usa un'azione per pronunciare di nuovo la sua parola d'ordine.\n\nOgni creatura, a eccezione del personaggio, che vede la propria immagine riflessa nello specchio attivato e si trova entro 9 metri da esso deve superare un tiro salvezza su Carisma con CD 15, altrimenti resta intrappolata in una delle dodici celle extradimensionali dello specchio, insieme a tutto ciò che indossa o trasporta. Se conosce la proprietà dello specchio, dispone di vantaggio al tiro salvezza; i costrutti superano il tiro salvezza automaticamente.\n\nUna cella extradimensionale è una distesa infinita di spazio pervasa da una fitta nebbia che riduce la visibilità a 3 metri. Le creature intrappolate nelle celle dello specchio non invecchiano e non hanno bisogno di mangiare, bere o dormire. Una creatura intrappolata in una cella può fuggire usando qualsiasi magia che consenta i viaggi planari; altrimenti, rimane confinata al suo interno finché non viene liberata.\n\nSe lo specchio intrappola una creatura, ma tutte le sue dodici celle sono occupate, una delle creature intrappolate (scelta casualmente) viene liberata per fare spazio al nuovo prigioniero. Una creatura liberata appare in uno spazio libero a portata di vista dello specchio, ma rivolta nella direzione opposta. Se lo specchio va in frantumi, tutte le creature che contiene vengono liberate e appaiono in spazi liberi vicino a esso.\n\nMentre si trova entro 1,5 metri dallo specchio, il personaggio può usare un'azione per pronunciare il nome di una creatura intrappolata all'interno o il numero di una cella. La creatura nominata o custodita nella cella di quel numero compare come immagine sulla superficie dello specchio. A questo punto, il personaggio e la creatura possono comunicare normalmente.\n\nAllo stesso modo, il personaggio può usare un'azione per pronunciare una seconda parola d'ordine e liberare una creatura intrappolata che compare, insieme a tutto ciò che possiede, nello spazio libero più vicino allo specchio, con le spalle rivolte a esso."),
			("Mirror of Life Trapping", "Wondrous item, very rare",
			"When this 4-foot-tall mirror is viewed indirectly, its surface shows faint images of creatures. The mirror weighs 50 pounds, and it has AC 11, 10 hit points, and vulnerability to bludgeoning damage. It shatters and is destroyed when reduced to 0 hit points.\n\nIf the mirror is hanging on a vertical surface and you are within 5 feet of it, you can use an action to speak its command word and activate it. It remains activated until you use an action to speak the command word again.\n\nAny creature other than you that sees its reflection in the activated mirror while within 30 feet of it must succeed on a DC 15 Charisma saving throw or be trapped, along with anything it is wearing or carrying, in one of the mirror's twelve extradimensional cells. This saving throw is made with advantage if the creature knows the mirror's nature, and constructs succeed on the saving throw automatically.\n\nAn extradimensional cell is an infinite expanse filled with thick fog that reduces visibility to 10 feet. Creatures trapped in the mirror's cells don't age, and they don't need to eat, drink, or sleep. A creature trapped within a cell can escape using magic that permits planar travel. Otherwise, the creature is confined to the cell until freed.\n\nIf the mirror traps a creature but its twelve extradimensional cells are already occupied, the mirror frees one trapped creature at random to accommodate the new prisoner. A freed creature appears in an unoccupied space within sight of the mirror but facing away from it. If the mirror is shattered, all creatures it contains are freed and appear in unoccupied spaces near it.\n\nWhile within 5 feet of the mirror, you can use an action to speak the name of one creature trapped in it or call out a particular cell by number. The creature named or contained in the named cell appears as an image on the mirror's surface. You and the creature can then communicate normally.\n\nIn a similar way, you can use an action to speak a second command word and free one creature trapped in the mirror. The freed creature appears, along with its possessions, in the unoccupied space nearest to the mirror and facing away from it.", null));
	}
}
